-- Spires of Arak: English quest texts that were missing (titles, descriptions and completion logs)

UPDATE `quest_template` SET `LogTitle` = 'Defungination', `LogDescription` = 'Use the QR58 Flame Blaster to destroy 20 Spore Pustules.', `QuestDescription` = 'Have you seen the fungus out there in the water? It''s growing faster than a baby ravasaur from Un''goro, and if we don''t get it under control, the Gearworks is gonna be ruined like our last village.$b$bUncle Krixel used to tell me to burn away the red fungus because that''s what makes it grow so fast.$b$bYou could help us out by taking a flame blaster and clearing out some of those spores down in the shallows.', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35077 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'Spore-be-Gone', `LogDescription` = 'Activate 6 Spore-be-Gone Turrets.', `QuestDescription` = 'We got an emergency!$b$bA bunch of spore drifters have infested the shore and tore up our Spore-B-Gone turrets.$b$bWe''re caught with our armor off here! If we don''t get those turrets back online then those spores are going to float right in to town and then we''ll have another Pinchwhistle Point on our hands!$b$bWe need to get out there and manually activate them.$b$bWell? Are you in?', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35079 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'The Mother Lode', `LogDescription` = 'Meet up with Kimzee Pinchwhistle at the Wreck of the Mother Lode.', `QuestDescription` = 'Hey we got ourselves a crisis here! Our zeppelin "The Mother Lode" crashed onto the south mountain range.$b$bIt was supposed to only be on an observation mission, what could have happened?$b$bWe got to get down there quick and I''m going to need your help on this.$b$bAre you with me?', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35080 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'Clearing Out Before Cleaning Up', `LogDescription` = 'Kill $1oa Crimsonwing Wasps.', `QuestDescription` = 'Here''s the situation.$b$bWe need to get this salvage operation moving ASAP, but the ship went down right in the middle of the wasp nests.$b$bThe ugly bugs are all over the place, and I can''t call my team in here to start work until they''re taken care of.$b$bGo kill as many of ''em as you can and I''ll cut you in on some of the haul.', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35081 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'Getting the Crew Back Together', `LogDescription` = 'Revive 6 Injured Crewmen.', `QuestDescription` = 'Oh wow, the debris is all over the mountainside! The survivors won''t make it if we don''t do something quick. They need healing NOW!$b$bHere, take my bandages and go patch them up.', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35082 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'Skimming Off the Top', `LogDescription` = 'Collect $1oa Volatile Oil.', `QuestDescription` = 'That flying machine is our ticket out of here but its fuel tank is bone dry!$b$bWe''re right next to the oil fields but with the infected out there we don''t have time to run a line up here so we need to improvise.$b$bThe oil creatures moving next to the pumps out there are full of a highly potent mixture that I can drop right into the tank. Grab some of that oil for me and we''ll be one step closer to getting out of here.', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35089 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'The Right Parts for the Job', `LogDescription` = 'Use the G-14 Buster Rocket near Broken Shredders to retrieve Serviceable Gears.', `QuestDescription` = 'Uncle Krixel''s a tough one but he won''t be going anywhere on foot with his leg broken.$b$bHe has a flying machine he brought from Azeroth that can fly us out of here. Problem is, the engine''s busted.$b$bI''ll need some parts to fix the thing. My car''s wasted but those broken shredders just outside of town should have what we need. We don''t have time to break them down by hand so just use this rocket launcher and blow ''em apart. Anything that survives the blast should be strong enough to use on the engine.', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35090 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'Sporicide', `LogDescription` = 'Kill $1oa Spore Shamblers in Pinchwhistle Point.', `QuestDescription` = 'It''s revolting, absolutely disgusting, infuriating even!$b$bI''m talking about seeing those spore creatures walking around Pinchwhistle Point.$b$bWhile I''m working on the machine here how about you go out and kill off some of those spore creatures? I''ll feel a bit better knowing there are less of those things moving around.', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35091 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'Preventing the Worst', `LogDescription` = 'Place $1oa Firebombs within Pinchwhistle Point.', `QuestDescription` = 'Have you seen all the fungus on the buildings in Pinchwhistle Point? It''s only a matter of time ''til it releases enough spores to infest the whole coastline!$b$bThe remaining infected that are in Pinchwhistle Point will be too far gone for us to save later on, so let''s do the right thing and put them out of their misery and prevent an even worse outbreak.$b$bI made some firebombs that will burn the fungus down, but I''ll need you to place them while I set up the detonator.$b$bAre you up for it?', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35211 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'Follow that Hotrod!', `LogDescription` = 'Find Kimzee Pinchwhistle in Pinchwhistle Point.', `QuestDescription` = 'Miss Kimzee is one tough nugget but Pinchwhistle Point is too dangerous for her to handle alone. It''ll be a catastrophe for morale if our boss gets infected.$b$bI need to get these crewmen back to the Gearworks so I need you to go and make sure she is alright.$b$bHer uncle''s place is the tower just on the other side of the oil fields; I think you should look for her around there.', `AreaDescription` = '', `QuestCompletionLog` = 'Speak with Kimzee Pinchwhistle in Pinchwhistle Point.', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35285 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'What''s Theirs is Ours', `LogDescription` = 'Speak to Shadow Hunter Ukambe at Admiral Taylor''s Garrison.', `QuestDescription` = 'I found somethin'' else while I was scoutin'', boss.$B$BDa Alliance have a garrison just across da way, and der been no movement in or out of da place in a good while.$B$BDis be a golden opportunity to sack da place and bolster your coffers, commander.$B$BWhat do ya say? We do it together.', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35295 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'Flame On', `LogDescription` = 'Use the Firebomb Plunger then ride on Kimzee''s Flying Machine.', `QuestDescription` = 'Alright $n, we''ve saved as many as we could but now we need to make sure this disaster doesn''t spread any further.$b$bThe firebombs are wired up and ready to go.$b$bKimzee just finished work on the flying machine so we''re ready to ride back to the Gearworks as soon as we''re finished.$b$bYou''ve done all the hard work so I think you should get the honors of triggering it.', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35298 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'A Parting Favor', `LogDescription` = 'Gather $1oa Spectral Essences from restless spirits inside the garrison and use them to convince Alice Finn of her fate.', `QuestDescription` = 'I don''t know what happened. My crew and I must have been the first to fall.$B$BMy wife, the innkeeper, is in the same stupor you found me in. I can feel it... and there are others with her.$B$BPlease, give the townsfolk peace and show their essences to my wife. That should bring her back from that cold abyss.', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35339 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'When All Is Aligned', `LogDescription` = 'Fly upon Ka''alu and kill $1oa Adherents.', `QuestDescription` = 'The ravenspeaker acolytes have been equipped with Apexis interfaces, they just need to get close enough.$B$BCome, let us take to the skies and secure the Terrace of Dawn.$B$BWhen all is aligned, we shall turn the false suns against one another and the spires shall burn like torches!$B$BI look forward to penning your actions into history.', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35704 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'The Tinkertoss Twins', `LogDescription` = 'Speak to Filbert Tinkertoss in Murkbog.', `QuestDescription` = 'Commander, two gnomish smugglers passed by while you were out - Filbert and Dilbert Tinkertoss. They were headed towards the bog to the east.$B$BThey had all sorts of drilling equipment but didn''t seem to have any weapons.$B$BWhat do you think of offering them protection in exchange for some of their materials?$B$BI''ll jot down where they were headed in case you decide to go.', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35713 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'Attempted Murder', `LogDescription` = 'Speak to Hutou Featherwind to secure a flight to Shadow''s Vigil.', `QuestDescription` = 'Your bartender Lunzul is dying, commander. She''s been poisoned and needs an antidote immediately.$B$BOne of your scouts reported seeing a Shattered Hand orc nearby recently - that''s our best bet.$B$BThere is a small arakkoa camp to the east that sits near a known Shattered Hand encampment. I suggest we start our search there.$B$BI''ve already spoken to your flight master about securing us a flight; every second counts.', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 35907 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'Unwanted Pests', `LogDescription` = 'Kill 10 Spore Drifters or Fungal Hulks in Sporemist Shallows.', `QuestDescription` = 'Those creatures out in the shallows keep busting the turrets as fast as we can get them operational.$b$bI''m supposed to go clear them out but my blaster is completely busted; the damn thing barely can light a candle like this!$b$bCould you do me a favor and go kill a few of those pests while I get my blaster fixed at the shop?$b$bJust let Gazwitz know you covered for me so I can get reimbursed for the repair.', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 36179 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'Field Trial', `LogDescription` = 'Venture into Pinchwhistle Point and use the Vial of Untested Serum on an Infected Bruiser or Infected Lumberjack.  Return to Krixel Pinchwhistle to report the results.', `QuestDescription` = 'Look, I didn''t tell Kimzee about this because I don''t want to hurt her feelings, I chose not to leave Pinchwhistle Point.$b$bSee, I''ve been working on a serum that I think should be able to cure the infected, but when I tried to test it I got surrounded and I injured my leg during the escape.$b$bI know I''m on the right track but I need to test it. Do me a favor and take this vial and go try it out on one of the infected outside.', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 36384 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'Curing With Force', `LogDescription` = 'Cure $1oa Infected Goblins.', `QuestDescription` = 'The infection is getting stronger so I made some adjustments and I''m pretty sure I have the right formula now.$b$bIt should now work but it needs to have less competition with the infected blood for it to have any effect.$b$bThis means you will need to weaken them before you apply the serum for it to function properly.$b$bThe infection is getting more advanced and will soon be untreatable so we have this one shot to save as many as we can.', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 36428 AND `LogTitle` IS NULL;
UPDATE `quest_template` SET `LogTitle` = 'TBD', `LogDescription` = '', `QuestDescription` = '', `AreaDescription` = '', `QuestCompletionLog` = '', `PortraitGiverText` = '', `PortraitTurnInText` = '' WHERE `ID` = 36659 AND `LogTitle` IS NULL;
